test("listPage 满页不多取也不漏取", () => {
  // 满页必须真的给满 size 条（旧实现每页少返回最后一条）
  assert.deepEqual(listPage(0, 3), [1, 2, 3]);
});
test("listPage 逐页拼接还原全量且不重不漏", () => {
  // 任何 size 下，翻完所有页拼起来必须恰好等于原始数据（闭区间约定的不变量）
  for (const size of [1, 2, 3, 4, 7, 8]) {
    const seen = [];
    for (let n = 0; n * size < 7; n++) seen.push(...listPage(n, size));
    assert.deepEqual(seen, [1, 2, 3, 4, 5, 6, 7], `size=${size} 时拼接结果不对`);
  }
});

